package dev.ww40.buildertimer.data

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/** Names, per-level upgrade durations and Town Hall requirements keyed by export data ID; generated by tools/generate_game_data.py. */
class GameData(private val entries: Map<Int, Entry>) {

    @Serializable
    data class Entry(
        val name: String,
        val upgradeSeconds: Map<Int, Long> = emptyMap(),
        val requiredTownHall: Map<Int, Int> = emptyMap(),
        val topLevel: Int? = null,
    )

    fun name(dataId: Int): String = entries[dataId]?.name ?: "Unknown ($dataId)"

    fun upgradeSeconds(dataId: Int, targetLevel: Int): Long? = entries[dataId]?.upgradeSeconds?.get(targetLevel)

    /** The highest level in the game, or null when the game data lists no levels. */
    fun topLevel(dataId: Int): Int? = entries[dataId]?.topLevel

    /** Durations by target level, limited to levels open at [townHallLimit] when one is given. */
    fun upgradeSecondsByLevel(dataId: Int, townHallLimit: Int? = null): Map<Int, Long> {
        val entry = entries[dataId] ?: return emptyMap()
        if (townHallLimit == null) return entry.upgradeSeconds
        return entry.upgradeSeconds.filterKeys { (entry.requiredTownHall[it] ?: 0) <= townHallLimit }
    }

    companion object {
        private const val ASSET_NAME = "game_data.json"
        private val json = Json { ignoreUnknownKeys = true }

        @Volatile
        private var cached: GameData? = null

        fun fromJson(text: String): GameData = GameData(json.decodeFromString<Map<Int, Entry>>(text))

        fun load(context: Context): GameData = cached ?: synchronized(this) {
            cached ?: fromJson(context.assets.open(ASSET_NAME).bufferedReader().use { it.readText() })
                .also { cached = it }
        }
    }
}
